fn raw_command_help_text(app: &App) -> String {
    let catalog = yoctui_model::builtin_raw_catalog();
    let Some(command) = app.raw_mode.selected_command(catalog) else {
        return "No Raw command selected.\n\nSelect a command in the Workspace to inspect its exact catalog help."
            .into();
    };
    let availability = command.availability(app.workspace_compatibility.authority());
    let mut lines = vec![
        format!("Description: {}", command.reference.description),
        format!("Reference section: {}", command.reference.heading),
        format!("Template: {}", raw_command_template(command)),
        format!(
            "Availability: {}",
            raw_availability_label(availability.state)
        ),
    ];

    if availability.issues.is_empty() {
        lines.push("Reason: none".into());
    } else {
        for issue in &availability.issues {
            let capability = issue
                .capability
                .map_or_else(|| "reference".into(), |capability| capability.to_string());
            lines.push(format!("Reason [{capability}]: {}", issue.reason));
            lines.extend(
                issue
                    .limitations
                    .iter()
                    .map(|limitation| format!("Limitation [{capability}]: {limitation}")),
            );
        }
    }

    if availability.implementations.is_empty() {
        lines.push("Implementation: none selected".into());
    } else {
        lines.extend(
            availability
                .implementations
                .iter()
                .map(|(capability, implementation)| {
                    format!("Implementation [{capability}]: {implementation}")
                }),
        );
    }

    match &command.execution {
        yoctui_model::RawExecutionPolicy::Executable { template } => {
            lines.push(format!(
                "Interaction: {}",
                raw_interaction_label(template.interaction)
            ));
            lines.push(format!("Safety: {}", raw_safety_label(template.safety)));
        }
        yoctui_model::RawExecutionPolicy::ReferenceOnly { kind, .. } => {
            lines.push(format!(
                "Interaction: Reference only ({})",
                raw_reference_kind_label(*kind)
            ));
            lines.push("Safety: Unsupported reference".into());
        }
    }

    if command.parameters.is_empty() {
        lines.push("Parameters: none".into());
    } else {
        lines.push("Parameters:".into());
        lines.extend(command.parameters.iter().map(|parameter| {
            format!(
                "- {} {} · {} · {}",
                parameter.label,
                parameter.placeholder,
                raw_parameter_kind_label(parameter.kind),
                raw_parameter_presence_label(parameter.presence)
            )
        }));
    }
    lines.push(format!(
        "Favorite: {}",
        if app.raw_mode.is_favorite(&command.id) {
            "Yes"
        } else {
            "No"
        }
    ));
    lines.join("\n")
}

fn task_inspector_primary(inspector: &TaskInspectorRef<'_>) -> String {
    match inspector {
        TaskInspectorRef::None => {
            "No task selected.\nTask facts appear as typed BitBake events arrive.".into()
        }
        TaskInspectorRef::Waiting { count } => format!(
            "Task        unavailable\nRecipe      unavailable\nPN          unavailable\nPV          unavailable\nPR          unavailable\nState       {}\nProgress    unavailable\n\n{count} waiting tasks are known only as an aggregate.",
            task_state_label(TaskState::Waiting)
        ),
        TaskInspectorRef::Task {
            task,
            state,
            version,
            revision,
            ..
        } => format!(
            "Task        {}\nRecipe      {}\nPN          {}\nPV          {}\nPR          {}\nState       {}\nProgress    {}",
            task.task,
            task.recipe,
            task.recipe,
            version.unwrap_or("unavailable"),
            revision.unwrap_or("unavailable"),
            task_state_label(*state),
            task.progress
                .map_or_else(|| "unknown".into(), |value| format!("{value}%")),
        ),
    }
}

fn task_inspector_context(inspector: &TaskInspectorRef<'_>, now: SystemTime) -> String {
    match inspector {
        TaskInspectorRef::None => "Secondary facts, paths, and dependencies unavailable.".into(),
        TaskInspectorRef::Waiting { .. } => {
            "Worker      unavailable\nPID         unavailable\nStarted     unavailable\nElapsed     unavailable\nWorkdir     unavailable\nLog file    unavailable\nDependencies unavailable".into()
        }
        TaskInspectorRef::Task {
            task,
            workdir,
            ..
        } => {
            let dependencies = if task.dependencies.is_empty() {
                "none reported".into()
            } else {
                task.dependencies
                    .iter()
                    .map(|dependency| dependency.0.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            };
            format!(
                "Worker      {}\nPID         {}\nStarted     {}\nElapsed     {}\nWorkdir     {}\nLog file    {}\nDependencies {}",
                task.worker.as_deref().unwrap_or("unavailable"),
                task.pid
                    .map_or_else(|| "unavailable".into(), |pid| pid.to_string()),
                task.started
                    .map_or_else(|| "unavailable".into(), clock_text),
                task.elapsed_at(now)
                    .map_or_else(|| "unavailable".into(), format_duration),
                workdir.map_or_else(
                    || "unavailable".into(),
                    |path| path.display().to_string()
                ),
                task.log_path.as_ref().map_or_else(
                    || "unavailable".into(),
                    |path| path.display().to_string()
                ),
                dependencies,
            )
        }
    }
}

fn task_inspector_recent_lines<'a>(
    app: &App,
    inspector: &'a TaskInspectorRef<'a>,
) -> Vec<Line<'a>> {
    let TaskInspectorRef::Task { recent_logs, .. } = inspector else {
        return vec![Line::from("No task-specific log is available.")];
    };
    if recent_logs.is_empty() {
        return vec![Line::from(
            "Waiting for typed log entries for the selected task.",
        )];
    }
    recent_logs
        .iter()
        .map(|entry| {
            let marker = match entry.severity {
                Severity::Trace => "·",
                Severity::Info => "│",
                Severity::Warning => "!",
                Severity::Error => "✕",
            };
            Line::from(vec![
                Span::styled(format!("{marker} "), severity_style(app, entry.severity)),
                Span::styled(entry.message.as_str(), severity_style(app, entry.severity)),
            ])
        })
        .collect()
}

fn inspector_action_styles(app: &App) -> ActionListStyles {
    let palette = ThemePalette::for_app(app);
    ActionListStyles {
        enabled: palette.role(palette.primary_foreground, Modifier::empty()),
        disabled: palette.role(palette.disabled, Modifier::DIM),
        shortcut: palette.role(palette.accent, Modifier::BOLD),
        detail: palette.role(palette.secondary_foreground, Modifier::ITALIC),
    }
}

fn task_inspector_actions(app: &App) -> Vec<ActionListItem> {
    let active_build = matches!(
        app.build.status,
        BuildStatus::Running | BuildStatus::Parsing | BuildStatus::Cancelling
    );
    let mut actions = compatibility_workspace_actions(app, WorkspaceDestination::Tasks)
        .into_iter()
        .filter(|action| action.label != "Inspect task inventory")
        .map(|mut action| {
            if action.label == "Cancel active build" && !active_build {
                action.enabled = false;
                action.marker = "×";
                action.state = "Disabled".into();
                action
                    .details
                    .insert(0, "Reason: No active build can be cancelled.".into());
            }
            action
        })
        .collect::<Vec<_>>();
    actions.sort_by_key(|action| match action.label.as_str() {
        "Cancel active build" => 0,
        "Open Logs" => 1,
        "Build History" => 2,
        "Build options" => 3,
        _ => 4,
    });
    actions
}

fn bounded_status_line(value: String, width: u16) -> String {
    let width = usize::from(width);
    if value.chars().count() <= width {
        return value;
    }
    if width == 0 {
        return String::new();
    }
    value
        .chars()
        .take(width.saturating_sub(1))
        .chain(std::iter::once('…'))
        .collect()
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SystemStatusLine {
    text: String,
    tone: StatusTone,
}

fn status_tone_style(palette: &ThemePalette, tone: StatusTone) -> Style {
    match tone {
        StatusTone::Success => palette.role(palette.success, Modifier::BOLD),
        StatusTone::Warning => palette.role(palette.warning, Modifier::BOLD),
        StatusTone::Error => palette.role(palette.error, Modifier::BOLD),
        StatusTone::Running => palette.role(palette.running, Modifier::BOLD),
        StatusTone::Pending => palette.role(palette.pending, Modifier::BOLD),
        StatusTone::Accent => palette.role(palette.accent, Modifier::BOLD),
        StatusTone::Muted => palette.role(palette.muted, Modifier::DIM),
        StatusTone::Info => palette.role(palette.informational, Modifier::BOLD),
        StatusTone::Disabled => palette.role(palette.disabled, Modifier::DIM),
    }
}

fn stronger_tone(left: StatusTone, right: StatusTone) -> StatusTone {
    let rank = |tone| match tone {
        StatusTone::Error => 4,
        StatusTone::Warning => 3,
        StatusTone::Pending => 2,
        StatusTone::Disabled | StatusTone::Muted => 1,
        StatusTone::Success | StatusTone::Running | StatusTone::Accent | StatusTone::Info => 0,
    };
    if rank(left) >= rank(right) {
        left
    } else {
        right
    }
}

fn system_status_projection(app: &App, width: u16) -> Vec<SystemStatusLine> {
    let current = app.daemon.status == yoctui_model::ClientReplicaStatus::Current;
    let uptime = if current {
        app.daemon.telemetry.as_ref().map_or_else(
            || "unavailable".into(),
            |telemetry| format_duration(Duration::from_secs(telemetry.uptime_seconds)),
        )
    } else {
        "unavailable".into()
    };
    let active_jobs = if current {
        app.daemon.telemetry.as_ref().map_or_else(
            || "unavailable".into(),
            |value| value.active_jobs.to_string(),
        )
    } else {
        "unavailable".into()
    };
    let sessions = if current {
        app.daemon.pty_sessions.len().to_string()
    } else {
        "unavailable".into()
    };
    let clients = if current {
        app.daemon.connected_clients.to_string()
    } else {
        "unavailable".into()
    };
    let bitbake = if current {
        daemon_lifecycle_label(app.daemon.bitbake).to_owned()
    } else {
        "unavailable".into()
    };
    let bitbake_version = if current {
        app.workspace
            .bitbake_version
            .as_deref()
            .unwrap_or("unavailable")
    } else {
        "unavailable"
    };
    let workspace = app
        .workspace
        .build_dir
        .as_deref()
        .or(app.workspace.source_dir.as_deref())
        .map_or_else(|| "unavailable".into(), |path| path.display().to_string());
    let filesystem_sample = match (
        utilization_percent(
            app.host_telemetry.disk_total_bytes,
            app.host_telemetry.disk_available_bytes,
        ),
        app.host_telemetry.disk_total_bytes,
        app.host_telemetry.disk_available_bytes,
        app.workspace.build_dir.as_ref(),
    ) {
        (Some(percent), Some(total), Some(available), Some(_)) => {
            Some((percent, format_bytes_pair(available, total)))
        }
        _ => None,
    };
    let projection = app
        .compatibility_ui
        .project(&app.workspace_compatibility, app.daemon.status);
    let (compatibility, compatibility_tone) = match (current, projection.authority) {
        (false, _) => ("Unavailable".into(), StatusTone::Warning),
        (true, CompatibilityUiAuthorityStatus::Current { generation, mode }) => (
            format!(
                "{:?} g{generation} · A{} L{} U{} ?{}",
                mode,
                projection.summary.available,
                projection.summary.limited,
                projection.summary.unavailable,
                projection.summary.unknown + projection.summary.unsupported,
            ),
            match mode {
                yoctui_model::EnvironmentOperatingMode::Full => StatusTone::Success,
                yoctui_model::EnvironmentOperatingMode::Degraded
                | yoctui_model::EnvironmentOperatingMode::Diagnostic => StatusTone::Warning,
            },
        ),
        (true, CompatibilityUiAuthorityStatus::Unavailable { .. }) => {
            ("Unavailable".into(), StatusTone::Warning)
        }
    };
    let (daemon, daemon_tone) = match app.daemon.status {
        yoctui_model::ClientReplicaStatus::Disconnected => ("Disconnected", StatusTone::Error),
        yoctui_model::ClientReplicaStatus::Synchronizing => ("Synchronizing", StatusTone::Pending),
        yoctui_model::ClientReplicaStatus::Current => ("Connected", StatusTone::Success),
        yoctui_model::ClientReplicaStatus::Stale => ("Stale", StatusTone::Warning),
    };
    let bitbake_tone = if current {
        match app.daemon.bitbake {
            yoctui_model::ClientDaemonLifecycle::Running => StatusTone::Success,
            yoctui_model::ClientDaemonLifecycle::Connecting
            | yoctui_model::ClientDaemonLifecycle::Stopping => StatusTone::Pending,
            yoctui_model::ClientDaemonLifecycle::Failed
            | yoctui_model::ClientDaemonLifecycle::Lost => StatusTone::Error,
            yoctui_model::ClientDaemonLifecycle::Disconnected
            | yoctui_model::ClientDaemonLifecycle::Exited => StatusTone::Disabled,
        }
    } else {
        StatusTone::Disabled
    };
    let (filesystem, filesystem_tone) = filesystem_sample.map_or_else(
        || ("unavailable".into(), StatusTone::Warning),
        |(percent, pair)| {
            let tone = if percent >= 90 {
                StatusTone::Error
            } else if percent >= 70 {
                StatusTone::Warning
            } else {
                StatusTone::Success
            };
            (format!("{percent}% · {pair} free"), tone)
        },
    );
    let log_tone = if app.logs.dropped_errors > 0 {
        StatusTone::Error
    } else if app.logs.dropped > 0 {
        StatusTone::Warning
    } else {
        StatusTone::Success
    };
    let workspace_tone = if workspace == "unavailable" {
        StatusTone::Warning
    } else {
        StatusTone::Success
    };
    let host_tone = stronger_tone(stronger_tone(filesystem_tone, log_tone), workspace_tone);
    let host = if workspace == "unavailable" {
        format!("Workspace unknown · Build FS {filesystem}")
    } else if app.logs.dropped > 0 {
        format!(
            "Logs {} evicted ({} warning/{} error) · Build FS {filesystem} · Workspace {workspace}",
            app.logs.dropped, app.logs.dropped_warnings, app.logs.dropped_errors,
        )
    } else {
        format!("Build FS {filesystem} · Workspace {workspace}")
    };

    let lines = if width >= 40 {
        vec![
            (
                format!("Daemon {daemon} · version unavailable · up {uptime}"),
                daemon_tone,
            ),
            (
                format!("BitBake {bitbake} · v{bitbake_version} · Jobs {active_jobs}"),
                bitbake_tone,
            ),
            (
                format!("Compat {compatibility} · PTY {sessions} · Clients {clients}"),
                compatibility_tone,
            ),
            (host, host_tone),
        ]
    } else {
        vec![
            (
                format!("Daemon {daemon} · version unavailable"),
                daemon_tone,
            ),
            (
                format!("Up {uptime} · BitBake {bitbake} · v{bitbake_version}"),
                bitbake_tone,
            ),
            (
                format!(
                    "Compat {compatibility} · Jobs {active_jobs} · PTY {sessions} · Clients {clients}"
                ),
                compatibility_tone,
            ),
            (host, host_tone),
        ]
    };
    lines
        .into_iter()
        .map(|(text, tone)| SystemStatusLine {
            text: bounded_status_line(format!("{} {text}", tone.marker()), width),
            tone,
        })
        .collect()
}

fn system_status_text(app: &App, width: u16) -> String {
    system_status_projection(app, width)
        .into_iter()
        .map(|line| line.text)
        .collect::<Vec<_>>()
        .join("\n")
}

fn system_status_document(app: &App, width: u16) -> Text<'static> {
    let palette = ThemePalette::for_app(app);
    Text::from(
        system_status_projection(app, width)
            .into_iter()
            .map(|line| Line::styled(line.text, status_tone_style(&palette, line.tone)))
            .collect::<Vec<_>>(),
    )
}

fn push_inspector_section(
    lines: &mut Vec<Line<'static>>,
    app: &App,
    title: &'static str,
    body: &str,
) {
    if body.trim().is_empty() {
        return;
    }
    if !lines.is_empty() {
        lines.push(Line::default());
    }
    let palette = ThemePalette::for_app(app);
    lines.push(Line::styled(
        format!("▾ {title}"),
        palette.role(palette.heading, Modifier::BOLD),
    ));
    lines.extend(body.lines().map(|line| Line::from(line.to_owned())));
}

struct InspectorDocumentSections<'a> {
    primary: &'a str,
    secondary: Option<&'a str>,
    related_paths: &'a [String],
    recent_output: Option<&'a str>,
    actions: Option<&'a [ActionListItem]>,
    status: Option<&'a str>,
}

fn inspector_document(
    app: &App,
    sections: InspectorDocumentSections<'_>,
    width: u16,
) -> Text<'static> {
    let mut lines = Vec::new();
    push_inspector_section(&mut lines, app, "PRIMARY FACTS", sections.primary);
    if let Some(secondary) = sections.secondary {
        push_inspector_section(&mut lines, app, "SECONDARY FACTS", secondary);
    }
    if !sections.related_paths.is_empty() {
        push_inspector_section(
            &mut lines,
            app,
            "RELATED PATHS",
            &sections.related_paths.join("\n"),
        );
    }
    if let Some(output) = sections.recent_output {
        push_inspector_section(&mut lines, app, "RECENT OUTPUT", output);
    }
    if let Some(actions) = sections.actions.filter(|actions| !actions.is_empty()) {
        if !lines.is_empty() {
            lines.push(Line::default());
        }
        let palette = ThemePalette::for_app(app);
        lines.push(Line::styled(
            "▾ CONTEXTUAL ACTIONS",
            palette.role(palette.heading, Modifier::BOLD),
        ));
        lines.extend(action_list(actions, width, inspector_action_styles(app)).lines);
    }
    if let Some(status) = sections.status {
        push_inspector_section(&mut lines, app, "SYSTEM / COMPATIBILITY", status);
    }
    Text::from(lines)
}

fn inspector_related_paths(app: &App) -> Vec<String> {
    let path = match app.screen {
        Screen::Recipes => app
            .workspace
            .recipes
            .get(app.recipe_selection)
            .and_then(|recipe| recipe.file.clone()),
        Screen::Layers => app
            .layer_browser
            .as_ref()
            .and_then(|browser| {
                browser.selected_entry().map(|entry| {
                    if entry.path.is_absolute() {
                        entry.path.clone()
                    } else {
                        browser.root.join(&entry.path)
                    }
                })
            })
            .or_else(|| {
                app.workspace
                    .layers
                    .get(app.layer_selection)
                    .map(|layer| layer.path.clone())
            }),
        Screen::Logs => app.logs.selected().and_then(|entry| entry.path.clone()),
        Screen::Errors => app
            .logs
            .diagnostics()
            .nth(app.error_selection)
            .and_then(|entry| entry.path.clone()),
        Screen::Images => app
            .selected_image_artifact()
            .map(|artifact| artifact.identity.path.clone()),
        Screen::Sdk => app
            .selected_sdk_artifact()
            .map(|artifact| artifact.identity.path.clone()),
        Screen::BuildHistory => app
            .job_history_rows()
            .get(app.build_history_selection)
            .and_then(|row| match row {
                JobHistoryRowRef::Background(job) => job.context.path.clone(),
                JobHistoryRowRef::Build(_) => None,
            }),
        _ => None,
    };
    path.into_iter()
        .map(|path| path.display().to_string())
        .collect()
}

fn tasks_inspector(
    frame: &mut Frame,
    app: &App,
    area: Rect,
    now: SystemTime,
    task_rows: &[TaskRowRef<'_>],
) {
    let selected = task_rows.get(app.task_progress_scroll).copied();
    let focused = app.focus == FocusTarget::Inspector;
    if area.height < 35 {
        let inspector = app.task_inspector(selected, 0);
        let sections = Layout::vertical([Constraint::Min(10), Constraint::Length(7)]).split(area);
        frame.render_widget(
            Paragraph::new(format!(
                "{}\n{}",
                task_inspector_primary(&inspector),
                task_inspector_context(&inspector, now)
            ))
            .block(pane_block(app, "Inspector: Task", focused))
            .wrap(Wrap { trim: false }),
            sections[0],
        );
        let actions = task_inspector_actions(app);
        frame.render_widget(
            Paragraph::new(action_list(
                &actions,
                sections[1].width.saturating_sub(2),
                inspector_action_styles(app),
            ))
            .block(pane_block(app, "Contextual Actions", false)),
            sections[1],
        );
        return;
    }

    let show_system = area.height >= 40;
    let sections = if area.height == 40 {
        Layout::vertical([
            Constraint::Length(10),
            Constraint::Length(10),
            Constraint::Length(6),
            Constraint::Length(8),
            Constraint::Length(6),
        ])
        .split(area)
    } else if show_system {
        Layout::vertical([
            Constraint::Length(11),
            Constraint::Length(12),
            Constraint::Min(5),
            Constraint::Length(9),
            Constraint::Length(6),
        ])
        .split(area)
    } else {
        Layout::vertical([
            Constraint::Length(11),
            Constraint::Length(12),
            Constraint::Min(5),
            Constraint::Length(9),
        ])
        .split(area)
    };
    let recent_limit = usize::from(sections[2].height.saturating_sub(2));
    let inspector = app.task_inspector(selected, recent_limit);
    frame.render_widget(
        Paragraph::new(task_inspector_primary(&inspector))
            .block(pane_block(app, "Inspector: Task", focused))
            .wrap(Wrap { trim: false }),
        sections[0],
    );
    frame.render_widget(
        Paragraph::new(task_inspector_context(&inspector, now))
            .block(pane_block(
                app,
                "Secondary facts · Paths · Dependencies",
                false,
            ))
            .wrap(Wrap { trim: false }),
        sections[1],
    );
    frame.render_widget(
        Paragraph::new(Text::from(task_inspector_recent_lines(app, &inspector)))
            .block(pane_block(app, "Recent output · Recent Log (tail)", false))
            .wrap(Wrap { trim: false }),
        sections[2],
    );
    let actions = task_inspector_actions(app);
    frame.render_widget(
        Paragraph::new(action_list(
            &actions,
            sections[3].width.saturating_sub(2),
            inspector_action_styles(app),
        ))
        .block(pane_block(app, "Contextual Actions", false)),
        sections[3],
    );
    if show_system {
        frame.render_widget(
            Paragraph::new(system_status_document(
                app,
                sections[4].width.saturating_sub(2),
            ))
            .block(pane_block(app, "System Status", false))
            .wrap(Wrap { trim: false }),
            sections[4],
        );
    }
}

fn inspector(
    frame: &mut Frame,
    app: &App,
    area: Rect,
    now: SystemTime,
    task_rows: Option<&[TaskRowRef<'_>]>,
) {
    if app.screen == Screen::Tasks {
        tasks_inspector(frame, app, area, now, task_rows.unwrap_or_default());
        return;
    }
    if app.focus == FocusTarget::Navigator {
        frame.render_widget(
            Paragraph::new(compatibility_destination_detail(
                app,
                app.navigator_compatibility_destination(),
                area.width.saturating_sub(2),
            ))
            .block(pane_block(
                app,
                &format!("Inspector: {}", app.inspector_mode().label()),
                false,
            ))
            .wrap(Wrap { trim: false }),
            area,
        );
        return;
    }
    let details = match app.screen {
        Screen::Recipes => app.workspace.recipes.get(app.recipe_selection).map_or_else(
            || "No recipe selected.".into(),
            |recipe| recipe_inspector(app, recipe),
        ),
        Screen::Layers => app.layer_browser.as_ref().map_or_else(
            || {
                app.workspace.layers.get(app.layer_selection).map_or_else(
                    || "No layer selected.".into(),
                    |layer| {
                        format!(
                            "Layer: {}\nPath: {}\nPriority: {}\n\nEnter browses this layer.",
                            layer.name,
                            layer.path.display(),
                            layer
                                .priority
                                .map_or_else(|| "unknown".into(), |value| value.to_string())
                        )
                    },
                )
            },
            |browser| {
                browser.selected_entry().map_or_else(
                    || format!("Layer: {}\n\nThis layer is empty.", browser.layer),
                    |entry| {
                        let detail = layer_entry_metadata(app, browser, entry);
                        let preview = match browser.preview_kind {
                            PreviewKind::Binary => "Binary preview unavailable.",
                            PreviewKind::Text if !browser.preview.is_empty() => {
                                "Text preview is visible in the workspace."
                            }
                            _ => "Preview unavailable.",
                        };
                        format!("{detail}\n\n{preview}")
                    },
                )
            },
        ),
        Screen::Configuration => config_inspector(app),
        Screen::Logs => app.logs.selected().map_or_else(
            || "No logs retained.".into(),
            |entry| {
                format!(
                    "Time: {}\nSeverity: {:?}\nBuild: {}\nRecipe: {}\nTask: {}\nSource: {}\nProtected: {}",
                    timestamp_text(entry.timestamp),
                    entry.severity,
                    entry.build.as_deref().unwrap_or("unavailable"),
                    entry.recipe.as_deref().unwrap_or("unavailable"),
                    entry.task.as_deref().unwrap_or("unavailable"),
                    entry
                        .path
                        .as_ref()
                        .map_or_else(|| "unavailable".into(), |path| path.display().to_string()),
                    if entry.protected { "yes" } else { "no" },
                )
            },
        ),
        Screen::Errors => app
            .logs
            .diagnostics()
            .nth(app.error_selection)
            .map_or_else(
                || "No retained warnings or errors.".into(),
                |entry| diagnostic_detail(app, entry),
            ),
        Screen::Dependencies | Screen::LayerRelationships => dependency_inspector(app),
        Screen::Signatures => signature_detail_text(app),
        Screen::BuildHistory => app
            .job_history_rows()
            .get(app.build_history_selection)
            .copied()
            .map_or_else(
                || "No background jobs or completed builds are retained in this session.".into(),
                |row| job_history_detail(row, now),
            ),
        Screen::Packages => package_inspector_text(app),
        Screen::Images => image_artifact_inspector_text(app),
        Screen::Sdk => sdk_inspector_text(app),
        Screen::Testing => testing_inspector_text(app),
        Screen::Security => security_inspector_text(app),
        Screen::Qa => qa_inspector_text(app),
        Screen::RawMode => raw_command_help_text(app),
        Screen::Maintenance => maintenance_inspector_text(app),
        Screen::Compatibility => compatibility_inspector_text(app),
        _ => format!(
            "Target: {}\nStatus: {:?}\n\nSelect an item in the workspace to inspect its details.",
            app.build.target.as_deref().unwrap_or("not selected"),
            app.build.status
        ),
    };
    let destination = yoctui_model::workspace_screen_destination(app.screen);
    let actions = compatibility_workspace_actions(app, destination);
    let related_paths = inspector_related_paths(app);
    let secondary = matches!(app.screen, Screen::Dashboard | Screen::BuildHistory)
        .then(|| job_summary_label(app, area.width));
    let recent_output = match app.screen {
        Screen::Logs => app.logs.selected().map(|entry| entry.message.as_str()),
        Screen::BuildHistory => app
            .job_history_rows()
            .get(app.build_history_selection)
            .and_then(|row| match row {
                JobHistoryRowRef::Background(job) => {
                    job.output.back().map(|entry| entry.message.as_str())
                }
                JobHistoryRowRef::Build(_) => None,
            }),
        _ => None,
    };
    let status = (app.screen == Screen::Dashboard)
        .then(|| system_status_text(app, area.width.saturating_sub(2)));
    let document = inspector_document(
        app,
        InspectorDocumentSections {
            primary: &details,
            secondary: secondary.as_deref(),
            related_paths: &related_paths,
            recent_output,
            actions: (!actions.is_empty()).then_some(actions.as_slice()),
            status: status.as_deref(),
        },
        area.width.saturating_sub(2),
    );
    let title = format!("Inspector: {}", app.inspector_mode().label());
    frame.render_widget(
        Paragraph::new(document)
            .block(pane_block(app, &title, app.focus == FocusTarget::Inspector))
            .wrap(Wrap { trim: false }),
        area,
    );
}

#[allow(dead_code)]
fn build_progress_popup(frame: &mut Frame, app: &App, area: Rect) {
    let width = area.width.saturating_sub(14).clamp(50, 110);
    let height = area.height.saturating_sub(6).clamp(12, 28);
    let popup = Rect::new(
        (area.width.saturating_sub(width)) / 2,
        (area.height.saturating_sub(height)) / 2,
        width,
        height,
    );
    let mut task_lines = app
        .tasks
        .values()
        .map(|task| {
            format!(
                "  {:<28} {:<18} {:>3}%",
                task.recipe,
                task.task,
                task.progress.unwrap_or(0)
            )
        })
        .collect::<Vec<_>>();
    task_lines.sort();
    if task_lines.is_empty() {
        task_lines.push("  Waiting for BitBake task events…".into());
    }
    let cpu = app
        .host_telemetry
        .cpu_utilization_percent
        .map_or_else(|| "sampling".into(), |value| format!("{value}%"));
    let disk = app
        .host_telemetry
        .disk_available_bytes
        .map_or_else(|| "unavailable".into(), format_bytes);
    let parse = match (app.build.parse_current, app.build.parse_total) {
        (Some(current), Some(total)) if total > 0 => format!(
            "{current}/{total} ({:.0}%)",
            current as f64 / total as f64 * 100.0
        ),
        _ => "not parsing".into(),
    };
    clear_popup(frame, app, popup);
    frame.render_widget(
        Paragraph::new(format!(
            "Target: {}\nStatus: {:?}    Tasks: {} complete, {} active\nParse: {parse}    CPU: {cpu}    Free disk: {disk}\n\nActive recipe tasks:\n{}\n\nBitBake is running. c cancels the build.",
            app.build.target.as_deref().unwrap_or("unknown"),
            app.build.status,
            app.build.completed,
            app.tasks.len(),
            task_lines.join("\n"),
        ))
        .block(Block::default().title("Build progress").borders(Borders::ALL))
        .wrap(Wrap { trim: false }),
        popup,
    );
}

fn build_completion_popup(frame: &mut Frame, app: &App, area: Rect) {
    let width = area.width.saturating_sub(24).clamp(44, 90);
    let popup = Rect::new(
        (area.width.saturating_sub(width)) / 2,
        area.height.saturating_sub(9) / 2,
        width,
        9,
    );
    let result = match app.build.status {
        yoctui_model::BuildStatus::Completed => "completed successfully",
        yoctui_model::BuildStatus::Cancelled => "was cancelled",
        _ => "failed",
    };
    let action = if app.build.status == yoctui_model::BuildStatus::Failed && app.build.errors > 0 {
        "Press Enter to investigate Errors; any other key returns to Yoctui."
    } else {
        "Press any key to return to Yoctui."
    };
    clear_popup(frame, app, popup);
    frame.render_widget(
        Paragraph::new(format!(
            "Build {} for {}.\n\nTasks completed: {}\nWarnings: {}    Errors: {}    Exit code: {}\nElapsed: {}\n\n{}",
            result,
            app.build.target.as_deref().unwrap_or("unknown target"),
            app.build.completed,
            app.build.warnings,
            app.build.errors,
            app.build.exit_code.map_or_else(|| "unknown".into(), |code| code.to_string()),
            app.elapsed().map(format_duration).unwrap_or_else(|| "unknown".into()),
            action,
        ))
        .style(build_status_style(app))
        .block(dialog_block(app, "Build finished", DialogTone::Result))
        .wrap(Wrap { trim: true }),
        popup,
    );
}
fn recipe_editor(frame: &mut Frame, app: &App, editor: &RecipeEditor, area: Rect) {
    let width = area.width.saturating_sub(4).max(30);
    let height = area.height.saturating_sub(2).max(8);
    let popup = Rect::new(
        (area.width.saturating_sub(width)) / 2,
        (area.height.saturating_sub(height)) / 2,
        width,
        height,
    );
    clear_popup(frame, app, popup);
    let outer = dialog_block(
        app,
        format!("Recipe editor: {}", editor.recipe),
        DialogTone::Standard,
    );
    let inner = outer.inner(popup);
    frame.render_widget(outer, popup);
    let regions = Layout::vertical([Constraint::Min(4), Constraint::Length(1)]).split(inner);
    let columns = Layout::horizontal([Constraint::Percentage(35), Constraint::Percentage(65)])
        .split(regions[0]);
    let files = editor
        .files
        .iter()
        .enumerate()
        .map(|(index, path)| {
            format!(
                "{} {}",
                if index == editor.selection {
                    "▶"
                } else {
                    " "
                },
                path.display()
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    frame.render_widget(
        Paragraph::new(files)
            .block(
                Block::default()
                    .title(format!("Workspace file tree: {}", editor.recipe))
                    .borders(Borders::ALL),
            )
            .wrap(Wrap { trim: false }),
        columns[0],
    );
    let selected = editor
        .files
        .get(editor.selection)
        .map_or_else(|| "no file".into(), |path| path.display().to_string());
    let mode = if editor.editing {
        "editing"
    } else {
        "read-only"
    };
    let modified = if editor.dirty { " modified" } else { "" };
    let content = if editor.editing {
        format!("{}▏", editor.content)
    } else {
        editor.content.clone()
    };
    frame.render_widget(
        Paragraph::new(source_preview(&content, &selected, app))
            .block(
                Block::default()
                    .title(format!("{selected} ({mode}{modified})"))
                    .borders(Borders::ALL),
            )
            .wrap(Wrap { trim: false }),
        columns[1],
    );
    frame.render_widget(
        Paragraph::new(
            "↑/↓ file  Enter/e edit  Ctrl+S save  Ctrl+B build recipe  Esc return to Yoctui",
        )
        .style(dialog_styles(app).hint),
        regions[1],
    );
}
fn format_bytes_pair(used: u64, total: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];
    let mut divisor = 1_u64;
    let mut unit = 0;
    while total / divisor >= 1024 && unit < UNITS.len() - 1 {
        let Some(next) = divisor.checked_mul(1024) else {
            break;
        };
        divisor = next;
        unit += 1;
    }
    if unit == 0 {
        format!("{used}/{total} {}", UNITS[unit])
    } else {
        format!(
            "{:.1}/{:.1} {}",
            used as f64 / divisor as f64,
            total as f64 / divisor as f64,
            UNITS[unit]
        )
    }
}

fn ram_gauge_label(percent: u8, used: u64, total: u64, width: u16) -> String {
    if width >= 38 {
        format!(
            "RAM {percent:>3}% · {} / {}",
            format_bytes(used),
            format_bytes(total)
        )
    } else if width >= 28 {
        format!("RAM {percent}% · {}", format_bytes_pair(used, total))
    } else {
        format!("RAM {percent}%")
    }
}

fn render_ram_gauge(frame: &mut Frame, app: &App, area: Rect) {
    if area.is_empty() {
        return;
    }
    let palette = ThemePalette::for_app(app);
    let total = app.host_telemetry.memory_total_bytes;
    let available = app.host_telemetry.memory_available_bytes;
    if let (Some(percent), Some(total), Some(available)) =
        (utilization_percent(total, available), total, available)
    {
        let used = total - available;
        frame.render_widget(
            Gauge::default()
                .ratio(f64::from(percent) / 100.0)
                .label(ram_gauge_label(percent, used, total, area.width))
                .gauge_style(memory_meter_style(app, percent)),
            area,
        );
    } else {
        frame.render_widget(
            Paragraph::new("RAM ! unavailable")
                .style(palette.role(palette.disabled, Modifier::DIM)),
            area,
        );
    }
}

fn disk_gauge_label(
    percent: u8,
    available: u64,
    total: u64,
    build_dir: &std::path::Path,
    width: u16,
) -> String {
    if width >= 52 {
        format!(
            "BUILD FS {percent:>3}% · {} free · {}",
            format_bytes_pair(available, total),
            build_dir.display()
        )
    } else if width >= 34 {
        format!(
            "BUILD FS {percent}% · {} free",
            format_bytes_pair(available, total)
        )
    } else if width >= 16 {
        format!("BUILD FS {percent}%")
    } else {
        format!("FS {percent}%")
    }
}

fn render_disk_gauge(frame: &mut Frame, app: &App, area: Rect) {
    if area.is_empty() {
        return;
    }
    let palette = ThemePalette::for_app(app);
    let total = app.host_telemetry.disk_total_bytes;
    let available = app.host_telemetry.disk_available_bytes;
    let build_dir = app.workspace.build_dir.as_deref();
    if let (Some(percent), Some(total), Some(available), Some(build_dir)) = (
        utilization_percent(total, available),
        total,
        available,
        build_dir,
    ) {
        frame.render_widget(
            Gauge::default()
                .ratio(f64::from(percent) / 100.0)
                .label(disk_gauge_label(
                    percent, available, total, build_dir, area.width,
                ))
                .gauge_style(telemetry_meter_style(app, percent)),
            area,
        );
    } else {
        frame.render_widget(
            Paragraph::new("BUILD FS ! unavailable")
                .style(palette.role(palette.disabled, Modifier::DIM)),
            area,
        );
    }
}

fn format_rate(bytes_per_second: u64) -> String {
    format!("{}/s", format_bytes(bytes_per_second))
}

struct RateHistory<'a> {
    label: &'a str,
    compact_label: &'a str,
    current: Option<u64>,
    samples: &'a [u64],
    graph_color: Color,
}

fn render_rate_history(frame: &mut Frame, app: &App, area: Rect, rate: RateHistory<'_>) {
    if area.is_empty() {
        return;
    }
    let palette = ThemePalette::for_app(app);
    let label = if area.width >= 28 {
        rate.label
    } else {
        rate.compact_label
    };
    let text = rate.current.map_or_else(
        || format!("{label} ! unavailable"),
        |rate| format!("{label} {}", format_rate(rate)),
    );
    let text_style = if rate.current.is_some() {
        palette.role(rate.graph_color, Modifier::BOLD)
    } else {
        palette.role(palette.disabled, Modifier::DIM)
    };
    if area.width < 18 {
        frame.render_widget(Paragraph::new(text).style(text_style), area);
        return;
    }
    let label_width = if area.width >= 28 { 20 } else { 14 };
    let columns = Layout::horizontal([
        Constraint::Length(label_width.min(area.width)),
        Constraint::Min(1),
    ])
    .split(area);
    frame.render_widget(Paragraph::new(text).style(text_style), columns[0]);
    frame.render_widget(
        Sparkline::default()
            .data(rate.samples)
            .max(rate.samples.iter().copied().max().unwrap_or(1).max(1))
            .style(palette.role(rate.graph_color, Modifier::BOLD)),
        columns[1],
    );
}

