    #[test]
    fn next_generation_job_history_is_responsive_pinned_and_exact() {
        let mut app = App::new(10, 1_000);
        app.screen = Screen::BuildHistory;
        let states = [
            BackgroundJobStatus::Queued,
            BackgroundJobStatus::Starting,
            BackgroundJobStatus::Running,
            BackgroundJobStatus::Cancelling,
            BackgroundJobStatus::Succeeded,
            BackgroundJobStatus::Failed,
            BackgroundJobStatus::Cancelled,
            BackgroundJobStatus::Lost,
        ];
        for (index, status) in states.into_iter().enumerate() {
            let terminal = status.is_terminal();
            app.background_jobs
                .jobs
                .push_back(yoctui_model::BackgroundJob {
                    id: yoctui_model::BackgroundJobId(index as u64 + 1),
                    kind: BackgroundJobKind::Build,
                    title: format!("operation-{index}"),
                    status,
                    context: yoctui_model::BackgroundJobContext {
                        target: Some("core-image-minimal".into()),
                        recipe: Some("busybox".into()),
                        task: Some("do_compile".into()),
                        ..yoctui_model::BackgroundJobContext::default()
                    },
                    cancellation_supported: true,
                    progress: yoctui_model::BackgroundJobProgress::Indeterminate,
                    output: std::collections::VecDeque::new(),
                    retained_output_bytes: 0,
                    dropped_output_entries: 0,
                    warnings: 1,
                    errors: usize::from(matches!(
                        status,
                        BackgroundJobStatus::Failed | BackgroundJobStatus::Lost
                    )),
                    queued_at: UNIX_EPOCH + Duration::from_secs(index as u64),
                    started_at: (!matches!(status, BackgroundJobStatus::Queued))
                        .then_some(UNIX_EPOCH + Duration::from_secs(index as u64 + 1)),
                    finished_at: terminal
                        .then_some(UNIX_EPOCH + Duration::from_secs(index as u64 + 5)),
                    result: (status == BackgroundJobStatus::Succeeded).then_some(
                        yoctui_model::BackgroundJobResult {
                            summary: "completed result".into(),
                            artifacts: Vec::new(),
                        },
                    ),
                    error: matches!(
                        status,
                        BackgroundJobStatus::Failed | BackgroundJobStatus::Lost
                    )
                    .then_some(yoctui_model::BackgroundJobError {
                        summary: format!("{status:?} outcome"),
                        detail: Some("exact terminal detail".into()),
                    }),
                });
        }

        assert_eq!(
            job_history_columns(70),
            [
                JobHistoryColumn::Status,
                JobHistoryColumn::Operation,
                JobHistoryColumn::Context,
                JobHistoryColumn::Elapsed,
            ]
        );
        assert!(job_history_columns(90).contains(&JobHistoryColumn::Started));
        assert!(!job_history_columns(90).contains(&JobHistoryColumn::Finished));
        assert_eq!(job_history_columns(120).len(), 8);

        let failed = app
            .job_history_rows()
            .iter()
            .position(|row| {
                matches!(row, JobHistoryRowRef::Background(job) if job.status == BackgroundJobStatus::Failed)
            })
            .unwrap();
        app.build_history_selection = failed;
        let output = rendered_text_at(&app, 180, 34, UNIX_EPOCH + Duration::from_secs(100));
        for expected in [
            "4 jobs pinned",
            "· Queued",
            "… Starting",
            "▶ Running",
            "! Cancelling",
            "✓ Succeeded",
            "✕ Failed",
            "■ Cancelled",
            "? Lost",
            "Target / Context",
            "busybox:do_compile",
            "Outcome: Failed outcome — exact terminal detail",
        ] {
            assert!(output.contains(expected), "missing {expected}: {output}");
        }
        let first = app.job_history_rows()[0];
        assert!(
            matches!(first, JobHistoryRowRef::Background(job) if !job.status.is_terminal()),
            "active work stays pinned ahead of terminal history"
        );
    }

    #[test]
    fn next_generation_job_summary_is_shared_compact_and_authoritative() {
        let mut app = App::new(10, 1_000);
        for (index, status) in [
            BackgroundJobStatus::Queued,
            BackgroundJobStatus::Running,
            BackgroundJobStatus::Failed,
            BackgroundJobStatus::Succeeded,
        ]
        .into_iter()
        .enumerate()
        {
            app.background_jobs
                .jobs
                .push_back(yoctui_model::BackgroundJob {
                    id: yoctui_model::BackgroundJobId(index as u64 + 1),
                    kind: BackgroundJobKind::Build,
                    title: format!("job-{index}"),
                    status,
                    context: yoctui_model::BackgroundJobContext::default(),
                    cancellation_supported: true,
                    progress: yoctui_model::BackgroundJobProgress::Indeterminate,
                    output: std::collections::VecDeque::new(),
                    retained_output_bytes: 0,
                    dropped_output_entries: 0,
                    warnings: 0,
                    errors: usize::from(status == BackgroundJobStatus::Failed),
                    queued_at: UNIX_EPOCH,
                    started_at: (status != BackgroundJobStatus::Queued)
                        .then_some(UNIX_EPOCH + Duration::from_secs(1)),
                    finished_at: status
                        .is_terminal()
                        .then_some(UNIX_EPOCH + Duration::from_secs(2)),
                    result: None,
                    error: None,
                });
        }
        app.daemon.status = yoctui_model::ClientReplicaStatus::Current;
        for id in 10..12 {
            app.daemon.jobs.push(yoctui_model::ClientDaemonJobSummary {
                id,
                label: format!("daemon-{id}"),
                lifecycle: yoctui_model::ClientDaemonLifecycle::Running,
            });
        }

        let wide = "Active 1 · Queued 1 · Failed 1 · Recent complete 2 · Daemon-owned 2";
        assert_eq!(job_summary_label(&app, 100), wide);
        assert_eq!(job_summary_label(&app, 70), "A1 Q1 F1 Done2 D2");

        app.screen = Screen::Tasks;
        let embedded = rendered_text_at(&app, 180, 44, UNIX_EPOCH + Duration::from_secs(10));
        assert!(embedded.contains(wide), "{embedded}");

        app.screen = Screen::BuildHistory;
        let standalone = rendered_text_at(&app, 180, 34, UNIX_EPOCH + Duration::from_secs(10));
        assert!(standalone.contains("A1 Q1 F1 Done2 D2"), "{standalone}");

        app.daemon.status = yoctui_model::ClientReplicaStatus::Stale;
        assert_eq!(job_summary_label(&app, 70), "A1 Q1 F1 Done2");
        assert!(!job_summary_label(&app, 100).contains("Daemon-owned"));
    }
    #[test]
    fn dependency_workspace_renders_typed_partial_graph_paths_and_responsive_states() {
        let mut app = App::new(10, 1_000);
        app.screen = Screen::Dependencies;
        let root = DependencyNodeId::recipe("image");
        let task = DependencyNodeId::task("busybox", "do_compile");
        let orphan = DependencyNodeId::recipe("orphan");
        let (graph, _) = DependencyGraph::normalize(
            root.clone(),
            vec![
                yoctui_model::DependencyNode {
                    id: task.clone(),
                    provider: Some("/layers/meta/busybox.bb".into()),
                    log: Some("/build/tmp/log.do_compile".into()),
                },
                yoctui_model::DependencyNode::identity(orphan.clone()),
            ],
            vec![
                yoctui_model::DependencyEdge {
                    from: root.clone(),
                    to: task.clone(),
                    kind: DependencyEdgeKind::Task,
                },
                yoctui_model::DependencyEdge {
                    from: task.clone(),
                    to: root.clone(),
                    kind: DependencyEdgeKind::Task,
                },
            ],
            100,
            100,
        );
        app.dependency_graph = DependencyGraphState::Partial {
            graph,
            limitations: vec!["runtime edges unavailable".into()],
        };
        app.dependency_graph_selection = Some(task);
        let output = rendered_text(&app, 160, 36);
        assert!(output.contains("Dependency graph"));
        assert!(output.contains("busybox:do_compile"));
        assert!(output.contains("runtime edges unavailable"));
        assert!(output.contains("--task-->"));
        assert!(output.contains("/layers/meta/busybox.bb"));
        assert!(output.contains("Reverse / incoming"));
        for width in [129, 100, 80] {
            let output = rendered_text(&app, width, 24);
            assert!(output.contains("Dependency graph"));
        }

        app.focus = FocusTarget::Inspector;
        app.dependency_graph_selection = Some(orphan);
        let output = rendered_text(&app, 80, 24);
        assert!(output.contains("unreachable from root"));

        app.focus = FocusTarget::Workspace;
        app.dependency_graph = DependencyGraphState::NotLoaded;
        assert!(rendered_text(&app, 80, 24).contains("not loaded"));
        app.dependency_graph = DependencyGraphState::Loading { root: root.clone() };
        assert!(rendered_text(&app, 80, 24).contains("Stale rows are hidden"));
        app.dependency_graph = DependencyGraphState::AvailableEmpty { root: root.clone() };
        assert!(rendered_text(&app, 80, 24).contains("No dependency edges reported"));
        app.dependency_graph = DependencyGraphState::Failed {
            root,
            message: "server unavailable".into(),
        };
        assert!(rendered_text(&app, 80, 24).contains("server unavailable"));
    }
    #[test]
    fn dependency_workspace_reports_path_bounds_without_panicking() {
        let root = DependencyNodeId::recipe("node-0");
        let mut nodes = Vec::new();
        let mut edges = Vec::new();
        for index in 1..=66 {
            let previous = DependencyNodeId::recipe(format!("node-{}", index - 1));
            let current = DependencyNodeId::recipe(format!("node-{index}"));
            nodes.push(yoctui_model::DependencyNode::identity(current.clone()));
            edges.push(yoctui_model::DependencyEdge {
                from: previous,
                to: current,
                kind: DependencyEdgeKind::Build,
            });
        }
        let selected = DependencyNodeId::recipe("node-66");
        let (graph, _) = DependencyGraph::normalize(root, nodes, edges, 100, 100);
        let mut app = App::new(10, 1_000);
        app.screen = Screen::Dependencies;
        app.focus = FocusTarget::Inspector;
        app.dependency_graph = DependencyGraphState::Available(graph);
        app.dependency_graph_selection = Some(selected);
        assert!(rendered_text(&app, 80, 24).contains("path limit reached"));
    }
